    function setUp() public {
        club = new FootiumClub();
        club.initialize("URL");
        player = new FootiumPlayer();
        player.initialize(address(123), 1, "URL");

        club.grantRole(club.MINTER_ROLE(), address(this));
        player.grantRole(club.MINTER_ROLE(), address(this));

